// ─── Operator (portal agent harness) ────────────────────────────────────────

export const operatorSessions = sqliteTable('operator_sessions', {
  id: text('id').primaryKey(),
  title: text('title'),
  startedBy: text('started_by').notNull(), // lowercased user email
  startedAt: integer('started_at', { mode: 'timestamp' }).notNull(),
  lastMessageAt: integer('last_message_at', { mode: 'timestamp' }).notNull(),
  messageCount: integer('message_count').notNull().default(0),
})

export const operatorMessages = sqliteTable('operator_messages', {
  id: text('id').primaryKey(),
  sessionId: text('session_id')
    .notNull()
    .references(() => operatorSessions.id, { onDelete: 'cascade' }),
  role: text('role', { enum: ['user', 'assistant', 'tool'] }).notNull(),
  content: text('content', { mode: 'json' }).notNull(),
  tokensIn: integer('tokens_in').notNull().default(0),
  tokensOut: integer('tokens_out').notNull().default(0),
  costCents: integer('cost_cents').notNull().default(0),
  errorMessage: text('error_message'),
  confirmedAt: integer('confirmed_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
})

export const operatorPermissions = sqliteTable('operator_permissions', {
  id: text('id').primaryKey(),
  userEmail: text('user_email').notNull().unique(), // lowercased; unique per tenant DB
  enabled: integer('enabled', { mode: 'boolean' }).notNull().default(false),
  // Record<DomainKey, 'none' | 'read' | 'write' | 'destructive'>
  domains: text('domains', { mode: 'json' })
    .$type<Record<string, 'none' | 'read' | 'write' | 'destructive'>>()
    .notNull(),
  // Record<toolName, 'allow' | 'deny'>
  toolOverrides: text('tool_overrides', { mode: 'json' })
    .$type<Record<string, 'allow' | 'deny'>>()
    .notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  updatedBy: text('updated_by'),
})

// ─── Operator channel gateway (external channels → Operator) ────────────────
// One thread per provider conversation (Slack thread, Telegram chat, email
// subject chain). Each thread is backed by a normal operator_sessions row so
// channel conversations share history/persistence with the portal Operator.

export const operatorChannelThreads = sqliteTable(
  'operator_channel_threads',
  {
    id: text('id').primaryKey(),
    provider: text('provider').notNull(),
    bindingId: text('binding_id').notNull(),
    integrationInstanceId: text('integration_instance_id').notNull(),
    externalThreadId: text('external_thread_id').notNull(),
    externalConversationId: text('external_conversation_id'),
    operatorSessionId: text('operator_session_id')
      .notNull()
      .references(() => operatorSessions.id, { onDelete: 'cascade' }),
    startedByExternalUserId: text('started_by_external_user_id'),
    lastMessageAt: integer('last_message_at', { mode: 'timestamp' }).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  },
  (t) => [uniqueIndex('operator_channel_threads_provider_binding_thread_unique').on(t.provider, t.bindingId, t.externalThreadId)],
)

export const operatorChannelMessages = sqliteTable('operator_channel_messages', {
  id: text('id').primaryKey(),
  threadId: text('thread_id')
    .notNull()
    .references(() => operatorChannelThreads.id, { onDelete: 'cascade' }),
  direction: text('direction', { enum: ['inbound', 'outbound'] }).notNull(),
  providerMessageId: text('provider_message_id'),
  operatorMessageId: text('operator_message_id').references(() => operatorMessages.id, {
    onDelete: 'set null',
  }),
  externalUserId: text('external_user_id'),
  externalUserLabel: text('external_user_label'),
  text: text('text').notNull(),
  status: text('status', {
    enum: ['received', 'ignored', 'queued', 'sent', 'drafted', 'failed'],
  }).notNull(),
  reason: text('reason'),
  rawSummary: text('raw_summary', { mode: 'json' }).$type<Record<string, unknown>>(),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
})

export type OperatorSession = typeof operatorSessions.$inferSelect
export type OperatorMessage = typeof operatorMessages.$inferSelect
export type OperatorPermission = typeof operatorPermissions.$inferSelect
export type OperatorChannelThread = typeof operatorChannelThreads.$inferSelect
export type OperatorChannelMessage = typeof operatorChannelMessages.$inferSelect

// ─── Newsletter: Subscribers ─────────────────────────────────────────────────

export const newsletterSubscribers = sqliteTable(
  'newsletter_subscribers',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(), // stored lowercased
    name: text('name'),
    status: text('status', { enum: ['subscribed', 'unsubscribed'] })
      .notNull()
      .default('subscribed'),
    source: text('source', { enum: ['sdk', 'manual', 'import'] })
      .notNull()
      .default('sdk'),
    unsubscribedAt: integer('unsubscribed_at', { mode: 'timestamp' }),
    // Which issue's email triggered the unsubscribe. Plain text (no FK) so
    // subscriber rows survive issue deletion.
    unsubscribeIssueId: text('unsubscribe_issue_id'),
    createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  },
  (t) => [uniqueIndex('newsletter_subscribers_email_unique').on(t.email)],
)

// ─── Newsletter: Issues ──────────────────────────────────────────────────────

export const newsletterIssues = sqliteTable('newsletter_issues', {
  id: text('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  subject: text('subject').notNull(),
  previewText: text('preview_text'),
  content: text('content').notNull(), // markdown source
  status: text('status', { enum: ['draft', 'scheduled', 'sending', 'sent', 'failed'] })
    .notNull()
    .default('draft'),
  senderRef: text('sender_ref'), // JSON SenderRef
  scheduledAt: integer('scheduled_at', { mode: 'timestamp' }),
  scheduledJobId: text('scheduled_job_id'),
  sentAt: integer('sent_at', { mode: 'timestamp' }),
  recipientCount: integer('recipient_count').notNull().default(0),
  sentCount: integer('sent_count').notNull().default(0),
  failedCount: integer('failed_count').notNull().default(0),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
})

// ─── Newsletter: Sends (per-recipient delivery + engagement log) ─────────────

export const newsletterSends = sqliteTable(
  'newsletter_sends',
  {
    id: text('id').primaryKey(),
    issueId: text('issue_id')
      .notNull()
      .references(() => newsletterIssues.id, { onDelete: 'cascade' }),
    subscriberId: text('subscriber_id')
      .notNull()
      .references(() => newsletterSubscribers.id, { onDelete: 'cascade' }),
    email: text('email').notNull(), // snapshot at send time
    status: text('status', { enum: ['pending', 'sent', 'failed'] })
      .notNull()
      .default('pending'),
    messageId: text('message_id'),
    error: text('error'),
    openedAt: integer('opened_at', { mode: 'timestamp' }),
    openCount: integer('open_count').notNull().default(0),
    clickedAt: integer('clicked_at', { mode: 'timestamp' }),
    clickCount: integer('click_count').notNull().default(0),
    sentAt: integer('sent_at', { mode: 'timestamp' }),
    createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  },
  (t) => [uniqueIndex('newsletter_sends_issue_subscriber_unique').on(t.issueId, t.subscriberId)],
)

// ─── Update Lists ────────────────────────────────────────────────────────────
// A tenant can keep several independently-addressable feeds of short markdown
// items — announcements, an events calendar, a product changelog. The list is
// the addressable unit: the SDK fetches one by `slug`, so slugs are unique per
// tenant DB and stable once published.

export const updateLists = sqliteTable(
  'update_lists',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description'),
    createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  },
  (t) => [uniqueIndex('update_lists_slug_unique').on(t.slug)],
)

// ─── Update Items ────────────────────────────────────────────────────────────
// One entry in an update list. `body` is markdown. `eventDate` is set only for
// event-shaped items (a listing with a date attached); announcements leave it
// null and sort by `sortOrder` / `publishedAt` instead.

export const updateItems = sqliteTable('update_items', {
  id: text('id').primaryKey(),
  listId: text('list_id')
    .notNull()
    .references(() => updateLists.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  body: text('body').notNull().default(''), // markdown source
  imageUrl: text('image_url'),
  eventDate: integer('event_date', { mode: 'timestamp' }),
  status: text('status', { enum: ['draft', 'published'] })
    .notNull()
    .default('draft'),
  publishedAt: integer('published_at', { mode: 'timestamp' }),
  // Manual ordering override; null falls back to the natural date order.
  sortOrder: integer('sort_order'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
})
