import { eq, desc, and, count as drizzleCount } from 'drizzle-orm'
import { newsletterIssues } from '@growth-engine/types/schema'
import type { ClientDb } from './content'

const DEFAULT_LIMIT = 20
const MAX_LIMIT = 5000

function resolveLimit(limit?: number): number {
  if (limit === undefined) return DEFAULT_LIMIT
  if (limit <= 0) return MAX_LIMIT
  return Math.min(limit, MAX_LIMIT)
}

/**
 * The public-safe projection of a newsletter issue. Sender config, scheduling
 * internals, and per-recipient counts are deliberately excluded — the client
 * site only ever sees what belongs on a published archive page.
 */
export interface PublicNewsletterIssue {
  id: string
  slug: string
  subject: string
  previewText: string | null
  content: string
  sentAt: Date | null
}

export function toPublicNewsletterIssue(
  row: typeof newsletterIssues.$inferSelect,
): PublicNewsletterIssue {
  return {
    id: row.id,
    slug: row.slug,
    subject: row.subject,
    previewText: row.previewText,
    content: row.content,
    sentAt: row.sentAt,
  }
}

export interface GetNewsletterIssuesOptions {
  limit?: number | undefined
  offset?: number | undefined
}

export async function getNewsletterIssues(
  db: ClientDb,
  opts?: GetNewsletterIssuesOptions,
): Promise<PublicNewsletterIssue[]> {
  const limit = resolveLimit(opts?.limit)
  const offset = opts?.offset ?? 0

  const rows = await db
    .select()
    .from(newsletterIssues)
    .where(eq(newsletterIssues.status, 'sent'))
    .orderBy(desc(newsletterIssues.sentAt))
    .limit(limit)
    .offset(offset)

  return rows.map(toPublicNewsletterIssue)
}

export async function getNewsletterIssue(
  db: ClientDb,
  slug: string,
): Promise<PublicNewsletterIssue | null> {
  const rows = await db
    .select()
    .from(newsletterIssues)
    .where(and(eq(newsletterIssues.slug, slug), eq(newsletterIssues.status, 'sent')))
    .limit(1)

  const row = rows[0]
  return row ? toPublicNewsletterIssue(row) : null
}

export async function getNewsletterIssueCount(db: ClientDb): Promise<number> {
  const result = await db
    .select({ count: drizzleCount() })
    .from(newsletterIssues)
    .where(eq(newsletterIssues.status, 'sent'))

  return result[0]?.count ?? 0
}
