// ─── Form Types ─────────────────────────────────────────────────────────────

export type FormFieldType = 'text' | 'email' | 'tel' | 'textarea' | 'select' | 'checkbox' | 'number' | 'url'

export interface FormField {
	name: string
	label: string
	type: FormFieldType
	required: boolean
	placeholder?: string
	options?: string[]
	order: number
}

/**
 * What a form is FOR.
 *   - 'standard'   — an ordinary form. It may additionally show a newsletter
 *                    opt-in checkbox (see `newsletterOptIn`).
 *   - 'newsletter' — a dedicated newsletter signup form. EVERY submission
 *                    subscribes the email, and no opt-in checkbox is rendered
 *                    (the whole form is the opt-in).
 *
 * Lives in `settings` rather than its own column deliberately: `forms.settings`
 * is already the per-form config blob, so this needs no migration.
 */
export type FormKind = 'standard' | 'newsletter'

/**
 * Newsletter opt-in checkbox appended to a STANDARD form. Never pre-checked —
 * a pre-ticked consent box is not valid consent under GDPR, and the businesses
 * using this platform should not have to know that.
 */
export interface FormNewsletterOptIn {
	enabled: boolean
	/** Wording next to the checkbox. Defaults to DEFAULT_NEWSLETTER_OPT_IN_LABEL. */
	label?: string
}

/**
 * Reserved key the opt-in answer is stored under in `form_submissions.data`, so
 * the consent is auditable per submission. Prefixed to avoid colliding with a
 * user-defined field name. Shared by the SDK renderer, the SDK submit handler
 * and the portal's submissions viewer — never inline the string.
 */
export const NEWSLETTER_OPT_IN_FIELD = '__newsletterOptIn'

export const DEFAULT_NEWSLETTER_OPT_IN_LABEL = 'Email me your newsletter'

export interface FormSettings {
	successMessage?: string
	submitButtonText?: string
	/** Defaults to 'standard' when absent (every form predating this field). */
	kind?: FormKind
	newsletterOptIn?: FormNewsletterOptIn
	notifyEmails?: string[]
	replyToEmail?: string
	sendConfirmationEmail?: boolean
	confirmationEmailSubject?: string
	confirmationEmailMessage?: string
	useEmailTemplate?: boolean
	useEmailTemplateNotification?: boolean
	useEmailTemplateConfirmation?: boolean
	notificationEmailMessage?: string
	replyToFieldName?: string
	notificationFromEmail?: string
	confirmationFromEmail?: string
}

export interface Form {
	id: string
	slug: string
	name: string
	description: string | null
	fields: FormField[]
	settings: FormSettings | null
	status: 'active' | 'archived'
	createdAt: Date
	updatedAt: Date
}

export interface FormSubmission {
	id: string
	formId: string
	data: Record<string, unknown>
	metadata: Record<string, unknown> | null
	createdAt: Date
}
