import { asc, eq } from 'drizzle-orm'
import { variables } from '@growth-engine/types/schema'
import { getClientDb } from '../db'

const CACHE_HEADERS = {
	'Cache-Control': 's-maxage=60, stale-while-revalidate=300',
}

/**
 * Read-only variables route.
 *
 *   GET /api/rs/variables → { variables: { [key]: value } }
 *
 * ── Why company scope only ──────────────────────────────────────────────────
 * `variables.scope` is either `'company'` (tenant-wide values meant for the
 * public site — phone number, booking URL, price points) or `'user'` (values
 * scoped to a single portal user via `userId`). This handler is reachable by
 * every anonymous visitor of the client website, so returning user-scoped rows
 * would publish one person's private data to the whole internet. The scope
 * filter is the security boundary here, not a convenience — do not widen it.
 *
 * For the same reason the response is a flat `key → value` map: `note` is
 * internal operator commentary and `id`/`userId`/timestamps are editing
 * metadata, none of which belongs on a public page.
 *
 * Duplicate company keys are not prevented by the schema; rows are read oldest
 * first so the most recently updated value wins deterministically.
 *
 * Writes are not exposed: POST returns 405.
 */
export async function handleVariables(
	request: Request,
	tursoUrl: string,
	tursoAuthToken: string,
): Promise<Response> {
	try {
		if (request.method !== 'GET') {
			return Response.json({ error: 'Method not allowed' }, { status: 405 })
		}

		const db = getClientDb(tursoUrl, tursoAuthToken)

		const rows = await db
			.select({ key: variables.key, value: variables.value })
			.from(variables)
			.where(eq(variables.scope, 'company'))
			.orderBy(asc(variables.updatedAt))

		const map: Record<string, string> = {}
		for (const row of rows) {
			map[row.key] = row.value
		}

		return Response.json({ variables: map }, { headers: CACHE_HEADERS })
	} catch (err) {
		console.error('[sdk:variables] route error:', err)
		return Response.json({ error: 'Internal server error' }, { status: 500 })
	}
}
