import { and, eq, sql } from 'drizzle-orm'
import { updateItems, updateLists } from '@growth-engine/types/schema'
import { getClientDb } from '../db'

const CACHE_HEADERS = {
	'Cache-Control': 's-maxage=60, stale-while-revalidate=300',
}

const DEFAULT_LIMIT = 20
const MAX_LIMIT = 100

/**
 * The public-safe projection of an update list. Timestamps are editing
 * metadata, so only the four fields a public feed needs are exposed.
 */
export interface PublicUpdateList {
	id: string
	name: string
	slug: string
	description: string | null
}

/**
 * The public-safe projection of an update item. `status`, `sortOrder` and the
 * created/updated timestamps are internal and never leave the Brain — drafts
 * are filtered out entirely, so the client site cannot even tell they exist.
 */
export interface PublicUpdateItem {
	id: string
	title: string
	/** Markdown source. */
	body: string
	imageUrl: string | null
	eventDate: Date | null
	publishedAt: Date | null
}

/** Clamp `?limit=` to 1..MAX_LIMIT; anything unparseable falls back to the default. */
function parseLimit(limitParam: string | null): number {
	if (limitParam === null) return DEFAULT_LIMIT
	const n = Number.parseInt(limitParam, 10)
	if (Number.isNaN(n) || n < 1) return DEFAULT_LIMIT
	return Math.min(n, MAX_LIMIT)
}

/**
 * Read-only updates route. Two actions, both GET:
 *
 *   GET /api/rs/updates?action=lists
 *     → { lists: [{ id, name, slug, description }] }        (all lists, by name)
 *
 *   GET /api/rs/updates?action=items&list=<slug>&limit=<n?>
 *     → { list: { id, name, slug, description }, items: [...] }
 *
 * Only `status = 'published'` items are ever returned. Ordering is
 * `COALESCE(event_date, published_at, created_at) DESC` — event-shaped items
 * sort by the date of the event, announcements by when they went live, and
 * `created_at` is the final fallback because `published_at` is nullable even on
 * published rows. Writes are not exposed: POST returns 405.
 */
export async function handleUpdates(
	request: Request,
	tursoUrl: string,
	tursoAuthToken: string,
): Promise<Response> {
	try {
		if (request.method !== 'GET') {
			return Response.json({ error: 'Method not allowed' }, { status: 405 })
		}

		const url = new URL(request.url)
		const action = url.searchParams.get('action')

		const db = getClientDb(tursoUrl, tursoAuthToken)

		if (action === 'lists') {
			const lists = await db
				.select({
					id: updateLists.id,
					name: updateLists.name,
					slug: updateLists.slug,
					description: updateLists.description,
				})
				.from(updateLists)
				.orderBy(updateLists.name)

			return Response.json({ lists } satisfies { lists: PublicUpdateList[] }, {
				headers: CACHE_HEADERS,
			})
		}

		if (action === 'items') {
			const listSlug = url.searchParams.get('list')?.trim()
			if (!listSlug) {
				return Response.json({ error: 'A list slug is required' }, { status: 400 })
			}

			const listRows = await db
				.select({
					id: updateLists.id,
					name: updateLists.name,
					slug: updateLists.slug,
					description: updateLists.description,
				})
				.from(updateLists)
				.where(eq(updateLists.slug, listSlug))
				.limit(1)

			const list = listRows[0]
			if (!list) {
				return Response.json({ error: 'Update list not found' }, { status: 404 })
			}

			const limit = parseLimit(url.searchParams.get('limit'))

			const items = await db
				.select({
					id: updateItems.id,
					title: updateItems.title,
					body: updateItems.body,
					imageUrl: updateItems.imageUrl,
					eventDate: updateItems.eventDate,
					publishedAt: updateItems.publishedAt,
				})
				.from(updateItems)
				.where(and(eq(updateItems.listId, list.id), eq(updateItems.status, 'published')))
				.orderBy(
					sql`coalesce(${updateItems.eventDate}, ${updateItems.publishedAt}, ${updateItems.createdAt}) desc`,
				)
				.limit(limit)

			return Response.json(
				{ list, items } satisfies { list: PublicUpdateList; items: PublicUpdateItem[] },
				{ headers: CACHE_HEADERS },
			)
		}

		return Response.json({ error: 'Invalid action' }, { status: 400 })
	} catch (err) {
		const url = new URL(request.url)
		console.error(`[sdk:updates] route error (${url.search}):`, err)
		return Response.json({ error: 'Internal server error' }, { status: 500 })
	}
}
